// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.StringJoiner;
import java.util.TreeMap;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.algebra.BinaryTupleOperator;
import org.eclipse.rdf4j.query.algebra.QueryModelNode;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.query.explanation.TelemetryMetricNames;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsAvailability;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

/**
 * Real-planner guard for a statement pattern whose subject, predicate and object are all bound by the time it runs:
 * {@code ?c follows ?d} is joined after an opaque {@code FILTER (?b != ?c)} prefix in which {@code ?b knows ?c} binds
 * {@code ?c} and a VALUES block binds {@code ?d}. The mapped Frontier transition cannot see through the opaque filter,
 * so the factor arrives with only its isolated population. The selected plan must still probe the edge as a direct
 * {@code [S, P, O]} lookup per prefix row instead of scanning the {@code [S, P]} prefix (or the whole predicate) and
 * filtering the object afterwards.
 */
@Timeout(120)
class LmdbFullyBoundEdgeBehindOpaqueFilterPlanningTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String NS = "urn:fully-bound-planning:";
	private static final IRI KNOWS = VF.createIRI(NS + "knows");
	private static final IRI FOLLOWS = VF.createIRI(NS + "follows");
	private static final int KNOWS_EDGES = 40;
	private static final int TARGETS = 5;
	private static final int OTHER_FOLLOWED_PER_SUBJECT = 400;
	private static final int OTHER_FOLLOWERS_PER_TARGET = 2_000;

	@Test
	void fullyBoundEdgeBehindOpaqueFilterIsPlannedAsADirectLookup(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,ospc,psoc"));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			load(repository);
			LmdbPlannerAwait.rebuildSketchesIfEnabled(store);
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());

			try (SailRepositoryConnection connection = repository.getConnection()) {
				assertEquals(KNOWS_EDGES, QueryResults.asList(connection.prepareTupleQuery(query()).evaluate()).size(),
						"every knows edge closes through exactly one followed VALUES target");

				TupleExpr optimized = (TupleExpr) connection.prepareTupleQuery(query())
						.explain(Explanation.Level.Optimized)
						.tupleExpr();
				List<StatementPattern> edges = new ArrayList<>();
				optimized.visit(new AbstractQueryModelVisitor<RuntimeException>() {
					@Override
					public void meet(StatementPattern node) {
						if (FOLLOWS.equals(node.getPredicateVar().getValue())) {
							edges.add(node);
						}
					}
				});
				assertEquals(1, edges.size(), () -> "plan=" + optimized);
				StatementPattern edge = edges.getFirst();
				String diagnostic = describe(edge) + "\nplan=" + optimized;

				assertEquals("[S, P, O]", edge.getStringMetricPlanned(TelemetryMetricNames.PLANNED_LOOKUP_COMPONENTS),
						() -> "the prefix binds subject and object, so the edge must be a dependent [S, P, O] lookup; "
								+ diagnostic);
				assertEquals(3.0d, edge.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_INDEX_PREFIX_LENGTH),
						0.0d, () -> "the lookup must use the complete three-component key; " + diagnostic);
				double accessRows = edge.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_ACCESS_ROWS);
				assertTrue(accessRows >= 0.0d && accessRows <= 1.0d,
						() -> "a fully bound lookup reads at most one statement per invocation; " + diagnostic);
				double workRows = edge.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_WORK_ROWS);
				assertTrue(Double.isFinite(workRows) && workRows >= 0.0d,
						() -> "the selected lookup must carry a finite planned price; " + diagnostic);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static String describe(StatementPattern edge) {
		QueryModelNode parent = edge.getParentNode();
		StringJoiner joiner = new StringJoiner(", ");
		joiner.add("edgeStrings=" + new TreeMap<>(edge.getStringMetricsPlanned()));
		joiner.add("edgeDoubles=" + new TreeMap<>(edge.getDoubleMetricsPlanned()));
		joiner.add("edgeRows=" + edge.getResultSizeEstimate());
		joiner.add("edgeCost=" + edge.getCostEstimate());
		assertNotNull(parent);
		joiner.add("parent=" + parent.getSignature());
		if (parent instanceof BinaryTupleOperator binary) {
			joiner.add("parentAlgorithm=" + binary.getAlgorithmName());
			joiner.add("edgeIsRightArg=" + (binary.getRightArg() == edge));
			joiner.add("parentRows=" + binary.getResultSizeEstimate());
			joiner.add("parentCost=" + binary.getCostEstimate());
		}
		return joiner.toString();
	}

	private static String query() {
		StringJoiner targets = new StringJoiner(" ");
		for (int target = 0; target < TARGETS; target++) {
			targets.add("<" + target(target) + ">");
		}
		return "SELECT ?b ?c ?d WHERE {\n"
				+ "  {\n"
				+ "    VALUES ?d { " + targets + " }\n"
				+ "    ?b <" + KNOWS + "> ?c .\n"
				+ "    FILTER (?b != ?c)\n"
				+ "  }\n"
				+ "  ?c <" + FOLLOWS + "> ?d .\n"
				+ "}";
	}

	/**
	 * Each knows object follows exactly one VALUES target and many other subjects; each VALUES target also has many
	 * unrelated followers. Probing the edge with only its subject or only its object bound therefore reads hundreds to
	 * thousands of statements per binding, while the fully bound probe reads at most one.
	 */
	private static void load(SailRepository repository) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			for (int edge = 0; edge < KNOWS_EDGES; edge++) {
				IRI subject = VF.createIRI(NS + "b/" + edge);
				IRI object = VF.createIRI(NS + "c/" + edge);
				connection.add(subject, KNOWS, object);
				connection.add(object, FOLLOWS, target(edge % TARGETS));
				for (int other = 0; other < OTHER_FOLLOWED_PER_SUBJECT; other++) {
					connection.add(object, FOLLOWS, VF.createIRI(NS + "other/" + edge + "/" + other));
				}
			}
			for (int target = 0; target < TARGETS; target++) {
				for (int follower = 0; follower < OTHER_FOLLOWERS_PER_TARGET; follower++) {
					connection.add(VF.createIRI(NS + "follower/" + target + "/" + follower), FOLLOWS, target(target));
				}
			}
			connection.commit();
		}
	}

	private static IRI target(int index) {
		return VF.createIRI(NS + "target/" + index);
	}
}
